import numpy as np,json
from PIL import Image
m=json.load(open('/app/runs/000/meta.json'))
for c in ['front','topview','right','left']:
 im=np.array(Image.open(f'/app/runs/000/last/{c}.jpg')); d=np.load(f'/app/runs/000/depth_{c}.npy')[0].astype(float); yy,xx=np.indices(im.shape[:2]);mask=(im[:,:,1]>105)&(im[:,:,1]>im[:,:,0]*1.4)&(im[:,:,1]>im[:,:,2]*1.25)&(yy>60)&(yy<210)
 if c=='right': mask &= (xx<200)
 if c=='left': mask &= (xx<200)
 ys,xs=np.where(mask);k=np.array(m['cameras'][c]['intrinsic_cv']);t=np.array(m['cameras'][c]['cam2world_gl']);
 for label,u,v in [('mean',xs.mean(),ys.mean()),('middle',(xs.min()+xs.max())/2,(ys.min()+ys.max())/2)]:
  zz=np.median(d[ys,xs]);p=t@np.array([(u-160)*zz/k[0,0],-(v-120)*zz/k[1,1],-zz,1]);print(c,label,'uvd',round(u,2),round(v,2),round(zz,3),'world',np.round(p[:3],3))
